import './batch-background.js';
import './atelier-layout.js';
import {compactNavigation} from './compact-navigation.js';
import './workspace-ux.js';
import {uiIcon} from './ui-icons.js';
import './manual-arrows.js';
import {navigationPage} from './navigation.js';
import './i18n.js';
import {addUpdates} from './updates-ui.js';
import {getSettings,saveSettings,playSound,avatarSVG,escapeHTML as esc} from './settings.js';
const option=(value,label,current)=>`<option value="${value}" ${value===current?'selected':''}>${label}</option>`;
const select=(key,label,items,s)=>`<label>${label}<select data-setting="${key}">${items.map(([v,l])=>option(v,l,s[key])).join('')}</select></label>`;
const settingsPage=navigationPage(location.pathname)==='settings.html';
const dialog=document.createElement(settingsPage?'section':'dialog');dialog.id='preferences';if(settingsPage)document.querySelector('#settingsMount').append(dialog);else document.body.append(dialog);
const settingsStyle=document.createElement('link');settingsStyle.rel='stylesheet';settingsStyle.href=new URL('./preferences.css',import.meta.url).href;document.head.append(settingsStyle);
const switches=(keys,s)=>`<div class="preference-switches">${keys.map(([key,label])=>`<label class="preference-switch"><span>${label}</span><input type="checkbox" role="switch" data-setting="${key}" ${s[key]?'checked':''}><span class="switch-track" aria-hidden="true"></span></label>`).join('')}</div>`;
let settingsSection=settingsPage&&location.hash==='#coach'?'coach':settingsPage&&location.hash==='#app'?'app':'appearance';
function selectSettingsSection(name){settingsSection=name;dialog.querySelectorAll('[data-settings-section]').forEach(p=>p.hidden=p.dataset.settingsSection!==name);dialog.querySelectorAll('[data-settings-nav]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.settingsNav===name)));dialog.querySelector('.preferences-content').scrollTop=0}
export function renderSettings(){const s=getSettings();dialog.setAttribute('aria-labelledby','preferencesTitle');dialog.innerHTML=`
<div class="preferences-header"><div><h2 id="preferencesTitle">Impostazioni</h2></div><button class="dialog-close" aria-label="Chiudi impostazioni" id="closePreferences">×</button></div>
<div class="preferences-layout"><nav class="preferences-nav" aria-label="Sezioni delle impostazioni"><button data-settings-nav="appearance" aria-pressed="true"><span aria-hidden="true">◐</span>Aspetto</button><button data-settings-nav="game" aria-pressed="false"><span aria-hidden="true">♟</span>Partita</button><button data-settings-nav="coach" aria-pressed="false"><span aria-hidden="true">☺</span>Il tuo coach</button><button data-settings-nav="app" aria-pressed="false"><span aria-hidden="true">↻</span>Novità</button></nav>
<div class="preferences-content">
<section data-settings-section="appearance"><h3>Lingua e aspetto</h3><p class="section-description">Scegli la lingua e l’aspetto della scacchiera.</p><div class="settings-grid">${select('language','Lingua',[['it','Italiano'],['en','English'],['es','Español'],['fr','Français'],['de','Deutsch']],s)}${select('theme','Aspetto',[['system','Automatico · sistema'],['light','Chiaro'],['dark','Scuro']],s)}${select('board','Scacchiera',[['amethyst','Ametista'],['lavender','Lavanda'],['green','Verde classico'],['walnut','Noce'],['slate','Ardesia'],['ocean','Oceano'],['sand','Sabbia'],['rose','Rosa antico']],s)}${select('accent','Colore dettagli',[['apricot','Albicocca'],['jade','Giada'],['violet','Viola']],s)}${select('boardFrame','Cornice scacchiera',[['classic','Classica'],['wood','Legno'],['light','Sottile']],s)}${select('animation','Movimento dei pezzi',[['normal','Fluido'],['slow','Lento'],['off','Disattivato']],s)}</div><details class="translation-note"><summary>Informazioni sulle traduzioni</summary><p>Traduzioni di interfaccia e coach. Alcune note del catalogo e informazioni tecniche sono ancora in italiano.</p></details><p><a class="secondary" href="aggiorna.html">Aggiorna la web app</a> <a class="secondary" href="https://docs.google.com/forms/d/e/1FAIpQLSdvNCs9k79lAlXEOlCe3eK2VTybDyIK5MwRXZjz6vwnO9n9xg/viewform" target="_blank" rel="noopener noreferrer">Invia feedback</a></p></section>
<section data-settings-section="game" hidden><h3>Aiuti e suoni</h3><p class="section-description">Regola gli aiuti visivi e il suono durante la partita.</p>${switches([['coordinates','Coordinate sulla scacchiera'],['legal','Mostra mosse legali'],['sound','Suoni della scacchiera']],s)}<label>Volume <output id="soundVolumeValue">${Math.round(s.volume*100)}%</output><input aria-label="Volume dei suoni" data-setting="volume" type="range" min="0" max="1" step="0.05" value="${s.volume}"></label><label>Suono da provare<select id="soundCue"><option value="move">Mossa</option><option value="capture">Cattura</option><option value="check">Scacco</option><option value="mate">Scacco matto</option><option value="win">Vittoria</option><option value="loss">Sconfitta</option><option value="draw">Patta</option></select></label><button id="previewSound" ${s.sound?'':'disabled'}>Prova il suono</button><p class="section-description">Mosse, catture e scacco hanno suoni diversi. L’esito si sente solo nelle partite giocate.</p></section>
<section data-settings-section="coach" hidden><div class="coach-settings-preview"><div id="avatarPreview">${avatarSVG(s)}</div><div><span class="eyebrow">IL TUO ISTRUTTORE</span><h3 id="settingsCoachName" translate="no">${esc(s.coachName)}</h3><p>Un compagno illustrato, con lo stile che scegli tu.</p></div></div><label class="name-field">Nome del coach<input data-setting="coachName" maxlength="18" value="${esc(s.coachName)}"></label><div class="settings-grid">${select('avatarShape','Forma',[['round','Tondo'],['square','Squadrato'],['cat','Gatto']],s)}${select('avatarColor','Colore',[['sage','Salvia'],['sky','Cielo'],['plum','Lilla'],['sun','Miele'],['coral','Corallo'],['mint','Menta']],s)}${select('avatarEyes','Espressione',[['friendly','Curioso'],['focused','Concentrato'],['happy','Sorridente']],s)}${select('avatarAccessory','Accessorio',[['none','Nessuno'],['glasses','Occhiali'],['crown','Spilla a stella'],['headphones','Corona']],s)}</div><h4 class="settings-subheading">Come ti accompagna</h4><div class="settings-grid">${select('coachTone','Tono del coach',[['warm','Incoraggiante'],['direct','Diretto'],['quiet','Essenziale']],s)}${select('coachFrequency','Quando commentare',[['all','Ogni mia mossa'],['errors','Solo mosse da rivedere']],s)}</div>${switches([['coachHints','Consenti indizi strategici su richiesta']],s)}</section>
<section data-settings-section="app" hidden id="settingsUpdates"><h3>Novità di Plystreak</h3><ol class="release-list">
<li><strong>1.26.9</strong><p>Le revisioni complete restano in archivio e la sincronizzazione Chess.com funziona anche nelle altre pagine.</p></li>
<li><strong>1.26.8</strong><p><a href="install.html#windows">Scarica per Windows x64</a></p></li>
<li><strong>1.26.7</strong><p>Il tema viene applicato prima di mostrare la pagina.</p></li>
<li><strong>1.26.6</strong><p>Nuovi suoni della scacchiera e animazioni per cattura, scacco, arrocco e promozione.</p></li>
<li><strong>1.26.5</strong><p>Lezioni interattive con confronto delle mosse e tre ritmi di allenamento.</p></li>
<li><strong>1.26.4</strong><p>Stemma del cavallo e trama di sfondo coordinati al tema.</p></li>
</ol></section>
</div></div><div class="preferences-footer"><p id="settingsStatus" role="status">Preferenze salvate su questo dispositivo.</p><button id="resetSettings" class="text-button">Ripristina le impostazioni</button><button id="donePreferences" class="primary">Fatto</button></div>`;
addUpdates(dialog.querySelector('#settingsUpdates'));
selectSettingsSection(settingsSection);
dialog.querySelectorAll('[data-settings-nav]').forEach(b=>b.onclick=()=>selectSettingsSection(b.dataset.settingsNav));
dialog.querySelector('#closePreferences').hidden=settingsPage;dialog.querySelector('#donePreferences').textContent=settingsPage?'Torna alla revisione':'Fatto';dialog.querySelector('#closePreferences').onclick=dialog.querySelector('#donePreferences').onclick=()=>settingsPage?location.assign('index.html'):dialog.close();
dialog.onchange=e=>{const key=e.target.dataset.setting;if(!key)return;const saved=saveSettings({[key]:e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value,...(key.startsWith('avatar')||key.startsWith('coach')?{coachPreset:'custom'}:{})});dialog.querySelector('#soundVolumeValue').textContent=Math.round(getSettings().volume*100)+'%';dialog.querySelector('#previewSound').disabled=!getSettings().sound;dialog.querySelector('#avatarPreview').innerHTML=avatarSVG();dialog.querySelector('#settingsCoachName').textContent=getSettings().coachName;dialog.querySelector('#settingsStatus').textContent=saved?'Preferenze salvate su questo dispositivo.':'Memoria non disponibile: impostazioni attive solo in questa sessione.'};
dialog.querySelector('#previewSound').onclick=()=>playSound(dialog.querySelector('#soundCue').value);
dialog.querySelector('[data-setting="volume"]').oninput=e=>{dialog.querySelector('#soundVolumeValue').textContent=Math.round(Number(e.target.value)*100)+'%'};
dialog.querySelector('#resetSettings').onclick=async()=>{const {defaults}=await import('./settings.js');saveSettings(defaults);renderSettings();dialog.querySelector('#resetSettings').focus()}}
export function openSettings(section='appearance'){if(settingsPage){selectSettingsSection(section);return}location.href='settings.html'+(section==='coach'?'#coach':'')}
const header=document.querySelector('header');const nav=document.createElement('nav');nav.className='app-nav';nav.setAttribute('aria-label','Menu principale');const page=navigationPage(location.pathname);nav.innerHTML=[['index.html','Analizza'],['coach.html','Gioca'],['practice.html','Esercizi'],['progress.html','Progressi'],['live.html','Dal vivo'],['openings.html','Aperture']].map(([url,label])=>`<a href="${url}" ${page===url?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${uiIcon(({'live.html':'live','coach.html':'coach','index.html':'analysis','progress.html':'progress','practice.html':'practice','openings.html':'openings'})[url])}</span><span>${label}</span></a>`).join('')+`<button id="preferencesButton" aria-label="Impostazioni e avatar"><span class="nav-icon" aria-hidden="true">${uiIcon('settings')}</span><span class="settings-label-full">Impostazioni</span><span class="settings-label-short">Opzioni</span></button>`;header.append(nav);compactNavigation(nav,openSettings);document.querySelector('#preferencesButton').onclick=()=>openSettings();document.querySelectorAll('[data-open-settings]').forEach(b=>b.onclick=()=>openSettings('coach'));if(settingsPage){document.querySelector('#preferencesButton').setAttribute('aria-current','page');renderSettings()}

window.plystreakDesktop?.healthy().catch(()=>{});

// The mascot replaces the existing brand glyph without adding a floating overlay.
const brand=document.querySelector('.brand');
if(brand){
 brand.href='index.html';
 const icon=document.createElement('span');icon.className='ply-mascot';icon.setAttribute('aria-hidden','true');icon.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 88" fill="none"><path d="M40 8c24 6 35 23 32 48-1 8-4 14-8 20 4-30-4-48-24-68Z" fill="var(--accent)"/><path d="m34 4 3 13 16 13c7 7 8 18 2 25L33 75h23l7 8H17l4-12 23-25-18 7-15-8 10-18 13-10V4Z" fill="#F4E8D6"/><path d="m26 30 10-5-5 8-5-3Z" fill="#2A0F2B"/></svg>';
 const old=brand.querySelector('.brand-icon');if(old)old.replaceWith(icon);else{for(const node of brand.childNodes)if(node.nodeType===Node.TEXT_NODE)node.textContent=node.textContent.replace('♘','');brand.prepend(icon)}
}

const installLink=document.createElement("a");installLink.href="install.html";installLink.textContent="Installa Plystreak e prepara l’uso offline";installLink.className="text-button install-shortcut";document.querySelector("main")?.append(installLink);
